import{_ as t,o as a,c as s,a2 as r}from"./chunks/framework.Cu3jFwFD.js";const g=JSON.parse('{"title":"Day cycle, overtime and storm","description":"","frontmatter":{},"headers":[],"relativePath":"features/day-cycle-and-storm/design.md","filePath":"features/day-cycle-and-storm/design.md","lastUpdated":1794908281000}'),i={name:"features/day-cycle-and-storm/design.md"};function d(n,e,o,l,h,c){return a(),s("div",null,[...e[0]||(e[0]=[r(`<h1 id="day-cycle-overtime-and-storm" tabindex="-1">Day cycle, overtime and storm <a class="header-anchor" href="#day-cycle-overtime-and-storm" aria-label="Permalink to &quot;Day cycle, overtime and storm&quot;">​</a></h1><p><strong>Status:</strong> <span class="status-badge status-designed">DESIGNED</span> · <strong>Updated:</strong> 2026-11-17 · <a href="./../../GDD">GDD</a></p><p>Every normal day is a short shift that ends at a clock, followed by a tempting overtime where deliveries pay more while Zeus&#39;s storm hunts the van and keeps escalating until it kills. The player decides by playing when to run home. Serves <strong>Push your luck</strong> and <strong>Bro thinks he&#39;s smart</strong>.</p><h2 id="rules" tabindex="-1">Rules <a class="header-anchor" href="#rules" aria-label="Permalink to &quot;Rules&quot;">​</a></h2><ol><li><strong>Shift:</strong> the van starts at HQ; the shift clock counts down from the shift length (60 s, minus 10 s with Big Lightning Rod). Packages spawn during the shift (<a href="./../packages/design">packages</a>).</li><li><strong>Shift lightning</strong> follows the trial&#39;s danger (<a href="./../trials/design">trials</a>) (<a class="decision-ref" href="/hex-gdd/GDD#d-047">D‑047</a>, <a class="decision-ref" href="/hex-gdd/GDD#d-062">D‑062</a>): <ul><li>Danger 1: strikes only inside the lightning area (a circle around Zeus&#39;s palace and one around the Electrical Plant), one every 3 s per area, at a random point in the area.</li><li>Danger 2: one strike every 6 s at a random point within 40 m of the van, not aimed at it.</li><li>Danger 3: one strike every 2.5 s at a random point within 40 m of the van, not aimed at it.</li><li>Every interval varies ±30% at random. Each is a <code>strike</code> (<a href="./../hazards/design">hazards</a>).</li></ul></li><li><strong>HQ during the shift</strong> does nothing: the day cannot end before the clock reaches 0 (<a class="decision-ref" href="/hex-gdd/GDD#d-058">D‑058</a>).</li><li><strong>Overtime</strong> starts automatically when the clock reaches 0: a banner, a red pulse, and the HUD time bar turns into an OVERTIME label. From then on, entering the HQ zone and pressing E ends the day. Deliveries pay ×1.5. Overtime money is safe only once the day ends at HQ: a wreck forfeits it (<a href="./../damage-and-repair/design">damage-and-repair</a>).</li><li><strong>Overtime storm:</strong> <code>strike</code>s (<a href="./../hazards/design">hazards</a>) aim at the van&#39;s position plus its heading (lead). 95% land within 0.6 m of the aimed point, the rest are near misses 1.5–3 m away. After each strike there is a 30% chance of a second strike aimed a little further ahead. The gap between strikes ramps from 2.0 s to 0.85 s over the first 25 s of overtime. Shift lightning (rule 2) stops when overtime starts.</li><li><strong>Big strike:</strong> every 12–18 s in overtime a <code>big-strike</code> (<a href="./../hazards/design">hazards</a>) is aimed where the van will be halfway through its warning.</li><li><strong>Escalation</strong> (<a class="decision-ref" href="/hex-gdd/GDD#d-042">D‑042</a>, <a class="decision-ref" href="/hex-gdd/GDD#d-063">D‑063</a>): after the 25 s ramp, every 10 s the gap between strikes is multiplied by 0.8 (never below 0.25 s), one more simultaneous strike is added to each volley, and the big-strike interval is multiplied by 0.8. There is no fixed cutoff; the storm eventually makes survival impossible.<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>t = seconds since overtime started</span></span>
<span class="line"><span>if t &lt;= 25: gap = lerp(2.0, 0.85, t / 25); volley = 1</span></span>
<span class="line"><span>else:       k = floor((t - 25) / 10)</span></span>
<span class="line"><span>            gap = max(0.25, 0.85 * 0.8^k); volley = 1 + k</span></span>
<span class="line"><span>bigStrikeInterval = random(12, 18) * 0.8^max(0, k)</span></span></code></pre></div></li><li>What a strike does to the van, and what counters it, is defined once in <a href="./../hazards/design">hazards</a>.</li><li><strong>HQ is safe:</strong> while the van is inside the HQ zone in overtime the storm pauses.</li><li>The map edge is guarded by the <code>boundary</code> hazard (<a href="./../hazards/design">hazards</a>).</li><li>The boss day has no overtime: when its clock reaches 0 the day ends (<a href="./../boss-charon/design">boss-charon</a>).</li><li>The sky darkens as the shift runs out (direction). The HUD shows the clock as a bar, not numbers (hud).</li></ol><h2 id="numbers" tabindex="-1">Numbers <a class="header-anchor" href="#numbers" aria-label="Permalink to &quot;Numbers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Name</th><th>Value</th><th>Unit</th><th>What to watch in playtests</th></tr></thead><tbody><tr><td>Normal shift length</td><td>60 (<a class="decision-ref" href="/hex-gdd/GDD#d-030">D‑030</a>)</td><td>s</td><td></td></tr><tr><td>Shift lightning interval: danger 1 (per lightning area) / danger 2 / danger 3</td><td>3 / 6 / 2.5 (<a class="decision-ref" href="/hex-gdd/GDD#d-062">D‑062</a>) <mark class="tune">TUNE</mark></td><td>s</td><td>Danger 3 should hurt but not wreck a careful driver in one shift</td></tr><tr><td>Shift lightning interval random variation</td><td>±30 <mark class="tune">TUNE</mark></td><td>%</td><td></td></tr><tr><td>Shift lightning radius around the van (danger 2–3)</td><td>40 (<a class="decision-ref" href="/hex-gdd/GDD#d-062">D‑062</a>) <mark class="tune">TUNE</mark></td><td>m</td><td></td></tr><tr><td>Lightning area radius (danger 1)</td><td>35 <mark class="tune">TUNE</mark></td><td>m</td><td>Re-measure on the new city map</td></tr><tr><td>Overtime pay multiplier</td><td>×1.5</td><td>factor</td><td>About half of players still take at least one overtime delivery</td></tr><tr><td>Overtime strike gap, start → end of ramp</td><td>2.0 → 0.85 <mark class="tune">TUNE</mark></td><td>s</td><td></td></tr><tr><td>Overtime ramp length</td><td>25 <mark class="tune">TUNE</mark></td><td>s</td><td></td></tr><tr><td>Escalation step / gap factor / minimum gap</td><td>every 10 s / ×0.8 / 0.25 (<a class="decision-ref" href="/hex-gdd/GDD#d-063">D‑063</a>) <mark class="tune">TUNE</mark></td><td>s / factor / s</td><td>A skilled driver cannot survive past about 50–60 s of overtime</td></tr><tr><td>Overtime double-strike chance</td><td>30 <mark class="tune">TUNE</mark></td><td>%</td><td></td></tr><tr><td>Big-strike interval</td><td>12–18, shrinks with escalation <mark class="tune">TUNE</mark></td><td>s</td><td></td></tr><tr><td>Overtime aimed strikes / near misses</td><td>95 / 5; spread 0.6 m / 1.5–3 m <mark class="tune">TUNE</mark></td><td>% / m</td><td></td></tr></tbody></table><h2 id="edge-cases" tabindex="-1">Edge cases <a class="header-anchor" href="#edge-cases" aria-label="Permalink to &quot;Edge cases&quot;">​</a></h2><ul><li>Pausing freezes the clock and the storm.</li><li>A strike during the Zeus ward is turned away; it does not use the lightning shield.</li><li>The Day 1 tutorial may hold the clock until its script ends (later feature).</li><li>Entering HQ during the shift shows &quot;Come back after your shift&quot; and does nothing else.</li></ul><h2 id="history" tabindex="-1">History <a class="header-anchor" href="#history" aria-label="Permalink to &quot;History&quot;">​</a></h2><ul><li>2026-11-17: strike, big strike and boundary behaviour moved to <a href="./../hazards/design">hazards</a> (<a class="decision-ref" href="/hex-gdd/GDD#d-080">D‑080</a>); this note keeps the schedule.</li><li>2026-11-17: designed from the prototype. Replaces the old 06:00–20:00 hour table; Minotaur stays cut (<a class="decision-ref" href="/hex-gdd/GDD#d-023">D‑023</a>); the prototype&#39;s Zeus ultimate is replaced by escalation (<a class="decision-ref" href="/hex-gdd/GDD#d-042">D‑042</a>).</li><li>2026-11-17: made implementable: shift lightning placement and rates (<a class="decision-ref" href="/hex-gdd/GDD#d-062">D‑062</a>), escalation formula (<a class="decision-ref" href="/hex-gdd/GDD#d-063">D‑063</a>), one damage value (<a class="decision-ref" href="/hex-gdd/GDD#d-064">D‑064</a>), HQ only after the clock (<a class="decision-ref" href="/hex-gdd/GDD#d-058">D‑058</a>).</li></ul>`,11)])])}const u=t(i,[["render",d]]);export{g as __pageData,u as default};
